// LXR sound engine tables and constants, extracted from the LXR V2 firmware
// (github.com/erica-synths/lxr-desktop-app, GPL-3.0-only). Generated, do not edit.
// base64 -> ArrayBuffer without atob(), which an AudioWorklet doesn't have
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const dec = (s) => {
  const u = new Uint8Array(Math.floor(s.replace(/=+$/, '').length * 3 / 4));
  for (let i = 0, o = 0, bits = 0, n = 0; i < s.length && s[i] !== '='; i++) {
    bits = (bits << 6) | B64.indexOf(s[i]); n += 6;
    if (n >= 8) { n -= 8; u[o++] = (bits >> n) & 0xff; }
  }
  return u.buffer;
};

// sine_table[4097], int16
export const SINE_TABLE = new Int16Array(dec(""));
// triTable, recTable, sawTable: [11][1024] int16 each. Stored back to back in this order
// (the order the linker placed them), because the interpolating readers can read one
// sample past the end of a row.
export const TRI_TABLE = new Int16Array(dec(""));
export const REC_TABLE = new Int16Array(dec(""));
export const SAW_TABLE = new Int16Array(dec(""));
// transientData[12][2205], int8
export const TRANSIENT_DATA = new Int8Array(dec(""));
// MidiNoteFrequencies[128], float32
export const MIDI_NOTE_FREQ = new Float32Array(dec(""));
// initKit[254]: 8 bytes name, then parameter values from index 0
export const INIT_KIT = new Uint8Array(dec(""));
// parameterOrder[]: order the preset loader sends the parameters in
export const PARAMETER_ORDER = new Uint8Array(dec(""));

